function argbToStraight(values: number[]) {
  return new Uint8ClampedArray(
    values.flatMap((value) => [
      (value >>> 16) & 255,
      (value >>> 8) & 255,
      value & 255,
      value >>> 24,
    ]),
  );
}
function scene(color = 0) {
  return argbToStraight(Array(81).fill(color));
